const input = $input.first().json || {};
const required = ['tenantId','providerPhoneNumberId','senderId','providerMessageId'];
const missing = required.filter((k) => input[k] === undefined || input[k] === null || input[k] === '');
if (missing.length) throw new Error('CASE002_CONVERSATION_CONTEXT_INPUT_MISSING ' + missing.join(','));

const tenantId = String(input.tenantId);
const senderId = String(input.senderId).replace(/[^0-9]/g, '');
const timezone = 'America/Lima';
const now = new Date();
const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
const sessionKey = tenantId + ':' + senderId;
const session = store.sessions[sessionKey] || { step: 'idle' };

const currentDate = new Intl.DateTimeFormat('en-CA', {
  timeZone: timezone,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(now);

return [{
  json: {
    ...input,
    agentContext: {
      currentDate,
      timezone,
      step: String(session.step || 'idle'),
      known: {
        requestType: String(session.requestType || ''),
        customerReportedSummary: String(session.serviceSummary || ''),
        vehicleOperationalState: String(session.vehicleOperationalState || 'unknown'),
        plate: session.plate || ''
      },
      offeredSlots: Array.isArray(session.offeredSlots) ? session.offeredSlots.slice(0, 4) : [],
      proposedSlot: String(session.proposedSlot || ''),
      recentConversation: Array.isArray(session.history) ? session.history.slice(-8) : []
    }
  }
}];

const input = $input.first().json || {};
const required = ['tenantId','providerPhoneNumberId','senderId','providerMessageId'];
const missing = required.filter((k) => input[k] === undefined || input[k] === null || input[k] === '');
if (missing.length) throw new Error('CASE002_APPOINTMENT_AGENT_INPUT_MISSING ' + missing.join(','));

const text = String(input.text || '').trim();
if (!text) return [];

const tenantId = String(input.tenantId);
const providerPhoneNumberId = String(input.providerPhoneNumberId);
const senderId = String(input.senderId).replace(/[^0-9]/g, '');
const providerMessageId = String(input.providerMessageId);
const traceId = String(input.providerEventId || providerMessageId);
const now = new Date();
const timezone = 'America/Lima';

const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
store.appointments = store.appointments || {};
store.processedMessages = store.processedMessages || {};

if (store.processedMessages[providerMessageId]) return [];

const sessionKey = tenantId + ':' + senderId;
let session = store.sessions[sessionKey] || { step: 'idle' };

function fold(value) {
  return String(value || '').toLocaleLowerCase('es-PE')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}
const lower = fold(text);
const interpretation = (
  input.llmMeta && input.llmMeta.ok === true &&
  input.llmInterpretation &&
  input.llmInterpretation.mechanicalDiagnosisProduced === false
) ? input.llmInterpretation : null;

function interpretedIntent(name) {
  return !!interpretation && interpretation.intent === name;
}

function trimProcessed() {
  const entries = Object.entries(store.processedMessages);
  if (entries.length <= 500) return;
  entries.sort((a, b) => Number(a[1]) - Number(b[1]));
  for (const entry of entries.slice(0, entries.length - 500)) delete store.processedMessages[entry[0]];
}

function collectProtectedFacts(body) {
  const fallback = String(body || '');
  const facts = new Set();

  if (session.plate && fallback.includes(String(session.plate))) facts.add(String(session.plate));

  const slotCandidates = [];
  for (const slot of Array.isArray(session.offeredSlots) ? session.offeredSlots : []) {
    slotCandidates.push(slotLabel(slot));
  }
  if (session.proposedSlot) slotCandidates.push(slotLabel(session.proposedSlot));
  for (const label of slotCandidates) {
    if (label && fallback.includes(label)) facts.add(label);
  }

  for (const match of fallback.match(/\b[0-3]?\d\/[01]?\d\b/g) || []) facts.add(match);
  for (const match of fallback.match(/\b(?:[01]?\d|2[0-3]):[0-5]\d\b/g) || []) facts.add(match);
  for (const match of fallback.match(/\b[A-Z0-9]{3}-[A-Z0-9]{3}\b/g) || []) facts.add(match);
  for (const match of fallback.match(/(?:S\/|\$)\s?\d+(?:[.,]\d+)?/g) || []) facts.add(match);

  return Array.from(facts).slice(0, 24);
}

function response(body, action) {
  store.processedMessages[providerMessageId] = Date.now();
  trimProcessed();

  const fallbackText = String(body || '').slice(0, 1200);
  const responsePlan = {
    schemaVersion: 1,
    action: String(action || session.step || 'reply'),
    fallbackText,
    protectedFacts: collectProtectedFacts(fallbackText),
    forbiddenTerms: ['piloto','Level-2','sandbox','workflow','Gemini','calendario interno','provider','node','model','API']
  };

  session.history = Array.isArray(session.history) ? session.history : [];
  session.history.push(
    { role: 'user', content: text.slice(0, 1200) },
    { role: 'assistant', content: fallbackText }
  );
  if (session.history.length > 10) session.history = session.history.slice(-10);
  session.updatedAt = now.toISOString();
  store.sessions[sessionKey] = session;

  return [{
    json: {
      tenantId,
      providerPhoneNumberId,
      senderId,
      to: senderId,
      text: fallbackText,
      fallbackText,
      responsePlan,
      traceId,
      businessActionId: 'case002-appointment-agent:' + providerMessageId,
      idempotencyKey: 'case002-appointment-agent:' + providerPhoneNumberId + ':' + providerMessageId
    }
  }];
}

function save(nextStep) {
  if (nextStep) session.step = nextStep;
  session.updatedAt = now.toISOString();
  store.sessions[sessionKey] = session;
}

function activeAppointments() {
  return Object.values(store.appointments).filter((a) => {
    if (!a || a.tenantId !== tenantId || a.senderId !== senderId || a.status !== 'booked') return false;
    const starts = new Date(a.startsAt).getTime();
    return Number.isFinite(starts) && starts > now.getTime();
  });
}

function ymdInLima(date) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit'
  }).formatToParts(date);
  const map = Object.fromEntries(parts.map((p) => [p.type, p.value]));
  return map.year + '-' + map.month + '-' + map.day;
}

function weekdayIndexInLima(date) {
  const label = new Intl.DateTimeFormat('en-US', { timeZone: timezone, weekday: 'short' }).format(date);
  return ({Sun:0,Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6})[label];
}

function slotLabel(iso) {
  const parts = new Intl.DateTimeFormat('es-PE', {
    timeZone: timezone,
    weekday: 'long',
    day: '2-digit',
    month: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  }).formatToParts(new Date(iso));
  const map = Object.fromEntries(parts.map((p) => [p.type, p.value]));
  return map.weekday + ' ' + map.day + '/' + map.month + ' a las ' + map.hour + ':' + map.minute;
}

function extractPlate(value) {
  const upper = String(value || '').toUpperCase();
  const candidates = upper.match(/[A-Z0-9]{3}[- ]?[A-Z0-9]{3}/g) || [];
  for (const raw of candidates) {
    const compact = raw.replace(/[^A-Z0-9]/g, '');
    if (compact.length === 6 && /[A-Z]/.test(compact) && /[0-9]/.test(compact)) {
      return compact.slice(0, 3) + '-' + compact.slice(3);
    }
  }

  const candidate = String(interpretation?.plate || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (candidate.length === 6 && /[A-Z]/.test(candidate) && /[0-9]/.test(candidate)) {
    return candidate.slice(0, 3) + '-' + candidate.slice(3);
  }
  return null;
}

function classifyRequest(value) {
  const t = fold(value);
  if (/\b(garantia|repararon|misma falla|mismo ruido|volvio a fallar|comeback)\b/.test(t)) return 'warranty_or_comeback';
  if (/\b(varado|varada|grua|no prende|inmovilizado|inmovilizada|auxilio)\b/.test(t)) return 'roadside_assistance';
  if (/\b(mantenimiento|aceite|filtro|afinamiento|preventivo|kilometraje)\b/.test(t)) return 'scheduled_maintenance';
  if (/\b(inspeccion|revision tecnica|revisar antes de viaje)\b/.test(t)) return 'inspection_request';
  if (/\b(reparar|reparacion|cambiar|freno|pastilla|bateria|llanta)\b/.test(t)) return 'repair_request';
  if (/\b(ruido|vibra|vibracion|check engine|testigo|fuga|humo|falla|jala|tironea|calienta)\b/.test(t)) return 'diagnostic_request';

  const allowed = new Set([
    'scheduled_maintenance','diagnostic_request','repair_request','inspection_request',
    'warranty_or_comeback','bodywork_or_collision','roadside_assistance','other'
  ]);
  const inferred = String(interpretation?.requestType || 'other');
  return allowed.has(inferred) ? inferred : 'other';
}

function genericService(value) {
  const t = fold(value).replace(/\b(hola|buenas|quiero|quisiera|necesito|agendar|reservar|una|cita|para|mi|carro|auto|vehiculo|taller|mecanica|mecanico|por favor)\b/g, ' ').replace(/\s+/g, ' ').trim();
  return !t || /^(mantenimiento|revision|servicio)$/.test(t);
}

function needsOperationalState(requestType) {
  return requestType === 'diagnostic_request' || requestType === 'repair_request';
}

function detectOperationalState(value) {
  const t = fold(value);
  if (/\b(no prende|no arranca|varado|varada|inmovilizado|inmovilizada|no puede circular|no circula|grua)\b/.test(t)) return 'immobilized_reported';
  if (/\b(si|sí|normal|circula|anda|arranca|puede circular|puedo manejar|se mueve)\b/.test(t)) return 'drivable_reported';

  const inferred = String(interpretation?.vehicleOperationalState || 'unknown');
  if (inferred === 'drivable_reported' || inferred === 'immobilized_reported') return inferred;
  return null;
}

function parsePreference(value) {
  const t = fold(value);
  const pref = { recognized: false, targetYmd: null, daypart: null, exactHour: null };

  const todayIndex = weekdayIndexInLima(now);
  const isMorningPhrase = /\b(por la|en la) manana\b/.test(t) || /\btemprano\b/.test(t);
  const isTomorrow = /\bmanana\b/.test(t) && !isMorningPhrase;

  if (/\bpasado manana\b/.test(t)) {
    pref.targetYmd = ymdInLima(new Date(now.getTime() + 2 * 86400000));
    pref.recognized = true;
  } else if (isTomorrow) {
    pref.targetYmd = ymdInLima(new Date(now.getTime() + 86400000));
    pref.recognized = true;
  }

  const weekdays = [
    ['domingo',0],['lunes',1],['martes',2],['miercoles',3],['jueves',4],['viernes',5],['sabado',6]
  ];
  for (const pair of weekdays) {
    if (t.includes(pair[0])) {
      let ahead = (pair[1] - todayIndex + 7) % 7;
      if (ahead === 0) ahead = 7;
      pref.targetYmd = ymdInLima(new Date(now.getTime() + ahead * 86400000));
      pref.recognized = true;
      break;
    }
  }

  const dateMatch = t.match(/\b([0-3]?\d)[\/-]([01]?\d)(?:[\/-](20\d{2}))?\b/);
  if (dateMatch) {
    const year = dateMatch[3] || new Intl.DateTimeFormat('en-CA', {timeZone: timezone, year:'numeric'}).format(now);
    pref.targetYmd = String(year) + '-' + String(dateMatch[2]).padStart(2,'0') + '-' + String(dateMatch[1]).padStart(2,'0');
    pref.recognized = true;
  }

  if (isMorningPhrase) {
    pref.daypart = 'morning';
    pref.recognized = true;
  }
  if (/\b(tarde|despues del almuerzo)\b/.test(t)) {
    pref.daypart = 'afternoon';
    pref.recognized = true;
  }

  const pm = t.match(/\b([1-4])\s*(?:pm|p\.m\.)\b/);
  const am = t.match(/\b(9|11)\s*(?:am|a\.m\.)\b/);
  const h24 = t.match(/\b(09|9|11|14|16)(?::00)?\b/);
  if (pm) {
    const h = Number(pm[1]);
    pref.exactHour = h === 1 ? 13 : h === 2 ? 14 : h === 3 ? 15 : 16;
    pref.recognized = true;
  } else if (am) {
    pref.exactHour = Number(am[1]);
    pref.recognized = true;
  } else if (h24) {
    pref.exactHour = Number(h24[1]);
    pref.recognized = true;
  }

  if (!pref.recognized && interpretation?.schedulePreference?.recognized === true) {
    const ai = interpretation.schedulePreference;
    if (/^20\d{2}-[01]\d-[0-3]\d$/.test(String(ai.targetDate || ''))) {
      pref.targetYmd = String(ai.targetDate);
      pref.recognized = true;
    }

    const weekdayMap = {
      sunday:0, monday:1, tuesday:2, wednesday:3,
      thursday:4, friday:5, saturday:6
    };
    const wantedDay = weekdayMap[String(ai.weekday || '')];
    if (!pref.targetYmd && wantedDay !== undefined) {
      let ahead = (wantedDay - todayIndex + 7) % 7;
      if (ahead === 0) ahead = 7;
      pref.targetYmd = ymdInLima(new Date(now.getTime() + ahead * 86400000));
      pref.recognized = true;
    }

    if (ai.daypart === 'morning' || ai.daypart === 'afternoon') {
      pref.daypart = ai.daypart;
      pref.recognized = true;
    }

    const exact = String(ai.exactTime || '').match(/^(\d{2}):(\d{2})$/);
    if (exact) {
      pref.exactHour = Number(exact[1]);
      pref.recognized = true;
    }
  }

  return pref;
}

function availableSlots(pref, limit) {
  pref = pref || {};
  limit = limit || 4;
  const slots = [];
  const occupied = new Set(
    Object.values(store.appointments)
      .filter((a) => a && a.tenantId === tenantId && a.status === 'booked')
      .map((a) => a.startsAt)
  );

  for (let dayOffset = 1; dayOffset <= 14 && slots.length < limit; dayOffset++) {
    const cursor = new Date(now.getTime() + dayOffset * 86400000);
    const weekday = weekdayIndexInLima(cursor);
    if (weekday === 0 || weekday === 6) continue;
    const ymd = ymdInLima(cursor);
    if (pref.targetYmd && ymd !== pref.targetYmd) continue;

    for (const hour of [9,11,14,16]) {
      if (pref.daypart === 'morning' && hour >= 12) continue;
      if (pref.daypart === 'afternoon' && hour < 12) continue;
      if (pref.exactHour !== null && pref.exactHour !== undefined && hour !== pref.exactHour) continue;
      const startsAt = ymd + 'T' + String(hour).padStart(2,'0') + ':00:00-05:00';
      if (!occupied.has(startsAt)) slots.push(startsAt);
      if (slots.length >= limit) break;
    }
  }
  return slots;
}

function slotChoices(slots) {
  return slots.map((slot, i) => String(i + 1) + ') ' + slotLabel(slot)).join('\n');
}

function selectionIndex(value, offeredSlots) {
  const t = fold(value);
  const direct = t.match(/^\s*([1-4])\s*$/);
  if (direct) return Number(direct[1]) - 1;
  const words = { primero:0, primera:0, segundo:1, segunda:1, tercero:2, tercera:2, cuarto:3, cuarta:3 };
  for (const key of Object.keys(words)) if (new RegExp('\\b' + key + '\\b').test(t)) return words[key];

  const hour = t.match(/\b(9|09|11|14|16)(?::00)?\b/);
  if (hour) {
    const wanted = Number(hour[1]);
    const idx = (offeredSlots || []).findIndex((slot) => Number(new Intl.DateTimeFormat('en-US', {
      timeZone: timezone, hour:'2-digit', hour12:false
    }).format(new Date(slot))) === wanted);
    if (idx >= 0) return idx;
  }

  const aiRef = fold(interpretation?.selectedSlotReference || '');
  if (aiRef) {
    const ordinals = { first:0, primero:0, primera:0, second:1, segundo:1, segunda:1, third:2, tercero:2, tercera:2, fourth:3, cuarto:3, cuarta:3 };
    if (Object.prototype.hasOwnProperty.call(ordinals, aiRef)) return ordinals[aiRef];

    const aiHour = aiRef.match(/\b(09|9|11|14|16)(?::00)?\b/);
    if (aiHour) {
      const wanted = Number(aiHour[1]);
      const idx = (offeredSlots || []).findIndex((slot) => Number(new Intl.DateTimeFormat('en-US', {
        timeZone: timezone, hour:'2-digit', hour12:false
      }).format(new Date(slot))) === wanted);
      if (idx >= 0) return idx;
    }
  }

  return null;
}

function isYes(value) {
  const direct = /\b(si|sí|confirmo|confirmar|dale|ok|okay|correcto|reservalo|reserva)\b/.test(fold(value));
  const llmConfirmed = session.step === 'awaiting_confirmation'
    && interpretedIntent('confirm')
    && interpretation.explicitConfirmation === true;
  return direct || llmConfirmed;
}

function isNoOrChange(value) {
  return /\b(no|cambiar|cambio|otra hora|otro horario|otra fecha|mejor otro)\b/.test(fold(value))
    || interpretedIntent('change_preference');
}

function capturePreferenceFromCurrentTurn() {
  const pref = parsePreference(text);
  if (pref.recognized) session.preference = pref;
  return pref;
}

function friendlyPrefix() {
  const variants = ['Perfecto', 'Claro', 'Genial', 'Listo'];
  const seed = Array.from(providerMessageId).reduce((acc, ch) => acc + ch.charCodeAt(0), 0);
  return variants[seed % variants.length];
}

function askPlate() {
  save('awaiting_plate');
  const remembered = session.preference && session.preference.recognized
    ? ' Ya me quedé con el horario que me dijiste.'
    : '';
  return response(friendlyPrefix() + '.' + remembered + ' Ahora pásame la placa del vehículo, tipo ABC-123. Si no la tienes a la mano, dime "no tengo" y seguimos.');
}

function askPreference() {
  save('awaiting_preference');
  return response('Dime qué día y a qué hora te viene mejor. Me puedes hablar normal: "mañana por la tarde", "viernes a las 11" o "el lunes temprano".');
}

function routeAfterService() {
  if (session.requestType === 'roadside_assistance') {
    session.step = 'human_review';
    session.reason = 'urgent_assistance';
    save();
    return response('Por lo que me cuentas, esto requiere atención humana o auxilio y no una cita automática. No voy a asumir un diagnóstico ni que sea seguro conducir el vehículo.');
  }
  if (session.requestType === 'warranty_or_comeback') {
    session.step = 'human_review';
    session.reason = 'warranty_or_comeback';
    save();
    return response('Como parece estar relacionado con un trabajo previo o garantía, prefiero que un asesor revise el historial antes de crear una cita automática.');
  }
  if (needsOperationalState(session.requestType) && !session.vehicleOperationalState) {
    save('awaiting_operational_state');
    return response('Antes de seguir: ¿el vehículo puede circular por sus propios medios? Respóndeme como te salga, por ejemplo "sí, anda normal" o "no, está varado".');
  }
  return askPlate();
}

if (/\b(reiniciar|empezar de nuevo|reset)\b/.test(lower) || interpretedIntent('restart')) {
  session = { step: 'idle', startedAt: now.toISOString() };
  store.sessions[sessionKey] = session;
  return response('Listo, empezamos de nuevo. Cuéntame qué quieres hacerle al carro o qué le estás notando.');
}

if (/\b(hablar con (una )?(persona|asesor)|asesor humano|atencion humana)\b/.test(lower) || interpretation?.humanHelpRequested === true || interpretedIntent('human_help')) {
  session.step = 'human_review';
  session.reason = 'customer_requested_human';
  save();
  return response('De acuerdo. Dejo la conversación marcada para atención humana.');
}

if (/\b(mis citas|mi cita|ver cita)\b/.test(lower) || interpretedIntent('list_appointments')) {
  const active = activeAppointments();
  if (!active.length) return response('No tengo una cita futura registrada para este número.');
  const lines = active.slice(-3).map((a, i) =>
    String(i + 1) + '. ' + slotLabel(a.startsAt) + ' — ' + a.serviceSummary + (a.plate ? ' — placa ' + a.plate : '')
  );
  return response('Estas son tus próximas citas:\n' + lines.join('\n') + '\n\nPuedes decirme "cancela mi cita" si deseas anular la más reciente.');
}

if (/\b(cancelar cita|anular cita|cancelar mi cita)\b/.test(lower) || interpretedIntent('cancel')) {
  const active = activeAppointments().sort((a, b) => String(a.createdAt).localeCompare(String(b.createdAt)));
  if (!active.length) return response('No encuentro una cita futura para cancelar.');
  const appointment = active[active.length - 1];
  appointment.status = 'cancelled';
  appointment.cancelledAt = now.toISOString();
  session = { step: 'idle', lastAppointmentId: appointment.id, updatedAt: now.toISOString() };
  store.sessions[sessionKey] = session;
  return response('Listo, cancelé la cita del ' + slotLabel(appointment.startsAt) + '. Si quieres otra, cuéntame qué necesitas.');
}

if (session.step === 'human_review') {
  return response('Este caso quedó marcado para revisión humana. Si quieres iniciar otro caso distinto, escribe REINICIAR.');
}

if (session.step === 'idle') {
  const bookingIntent = /\b(cita|agend|reserv|taller|mecanic|mantenimiento|revision|freno|aceite|check engine|vibr|ruido|fuga|falla|inspeccion)\b/.test(lower)
    || (!!interpretation && (interpretation.intent !== 'other' || interpretation.requestType !== 'other'));
  if (!bookingIntent) {
    session = { step: 'awaiting_service', startedAt: now.toISOString(), updatedAt: now.toISOString() };
    store.sessions[sessionKey] = session;
    return response('Hola. Cuéntame con tus palabras qué necesitas hacerle al vehículo o qué estás notando. Puedo ayudarte a organizar una cita, pero no voy a inventar un diagnóstico.');
  }

  session = {
    step: 'idle',
    serviceSummary: String(interpretation?.customerReportedSummary || text).trim() || text,
    requestType: classifyRequest(text),
    startedAt: now.toISOString(),
    updatedAt: now.toISOString()
  };

  const plate = extractPlate(text);
  if (plate) session.plate = plate;

  const operational = detectOperationalState(text);
  if (operational) session.vehicleOperationalState = operational;
  capturePreferenceFromCurrentTurn();

  if (genericService(text)) {
    save('awaiting_service_detail');
    return response('Claro. Para dejar bien registrada la cita, cuéntame un poco más: ¿es un mantenimiento periódico como aceite/filtros, o hay algo específico que quieras revisar?');
  }

  if (session.plate && (!needsOperationalState(session.requestType) || session.vehicleOperationalState)) {
    return askPreference();
  }
  return routeAfterService();
}

if (session.step === 'awaiting_service') {
  session.serviceSummary = String(interpretation?.customerReportedSummary || text).trim() || text;
  session.requestType = classifyRequest(text);
  const plate = extractPlate(text);
  if (plate) session.plate = plate;
  const operational = detectOperationalState(text);
  if (operational) session.vehicleOperationalState = operational;
  capturePreferenceFromCurrentTurn();

  if (genericService(text)) {
    save('awaiting_service_detail');
    return response('Entiendo. ¿Qué tipo de mantenimiento o revisión quieres hacer? Por ejemplo aceite y filtros, frenos, una inspección antes de viaje, o revisar algún ruido o testigo.');
  }
  if (session.plate && (!needsOperationalState(session.requestType) || session.vehicleOperationalState)) return askPreference();
  return routeAfterService();
}

if (session.step === 'awaiting_service_detail') {
  const detailSummary = String(interpretation?.customerReportedSummary || text).trim() || text;
  session.serviceSummary = (session.serviceSummary ? session.serviceSummary + ' | ' : '') + detailSummary;
  session.requestType = classifyRequest(session.serviceSummary);
  const operational = detectOperationalState(text);
  if (operational) session.vehicleOperationalState = operational;
  capturePreferenceFromCurrentTurn();
  const plate = extractPlate(text);
  if (plate) session.plate = plate;

  if (session.plate && (!needsOperationalState(session.requestType) || session.vehicleOperationalState)) return askPreference();
  return routeAfterService();
}

if (session.step === 'awaiting_operational_state') {
  const operational = detectOperationalState(text);
  if (!operational) {
    return response('Solo necesito confirmar esto para enrutar bien el caso: ¿el vehículo puede circular por sus propios medios, sí o no?');
  }
  session.vehicleOperationalState = operational;
  capturePreferenceFromCurrentTurn();
  if (operational === 'immobilized_reported') {
    session.step = 'human_review';
    session.reason = 'urgent_assistance';
    save();
    return response('Gracias. Como indicas que el vehículo no puede circular, no voy a crear una cita normal: dejo el caso para atención humana/auxilio.');
  }
  const plate = extractPlate(text);
  if (plate) session.plate = plate;
  if (session.plate) return askPreference();
  return askPlate();
}

if (session.step === 'awaiting_plate') {
  const noPlate = /\b(no tengo|sin placa|no la tengo)\b/.test(lower);
  const plate = extractPlate(text);
  if (!noPlate && !plate) {
    return response('No alcancé a reconocer la placa. Mándamela tipo ABC-123, o dime "no tengo" y seguimos igual.');
  }
  session.plate = noPlate ? null : plate;

  const prefFromThisTurn = parsePreference(text);
  if (prefFromThisTurn.recognized) session.preference = prefFromThisTurn;
  const pref = session.preference && session.preference.recognized ? session.preference : prefFromThisTurn;

  if (pref && pref.recognized) {
    const slots = availableSlots(pref, 4);
    if (slots.length) {
      session.offeredSlots = slots;
      save('awaiting_slot');
      return response(friendlyPrefix() + ', con eso ya tengo todo. Para el horario que me pediste encontré:\n\n' + slotChoices(slots) + '\n\n¿Cuál te acomoda mejor? Puedes decirme "el segundo", "el de las 11" o 1, 2, 3 o 4.');
    }
  }
  return askPreference();
}

if (session.step === 'awaiting_preference') {
  const pref = parsePreference(text);
  if (!pref.recognized) {
    return response('Dime cuándo te conviene de forma natural. Por ejemplo: "mañana por la tarde", "viernes a las 11" o "lunes temprano".');
  }

  session.preference = pref;
  let slots = availableSlots(pref, 4);
  let prefix = 'Encontré estas opciones que coinciden con lo que pediste:';
  if (!slots.length) {
    slots = availableSlots({}, 4);
    prefix = 'No tengo un espacio que coincida exactamente con eso. Lo más próximo disponible es:';
  }
  if (!slots.length) {
    session.step = 'human_review';
    session.reason = 'no_test_slots';
    save();
    return response('No encuentro horarios disponibles que pueda ofrecerte ahora. Voy a dejar el caso para revisión humana.');
  }
  session.offeredSlots = slots;
  save('awaiting_slot');
  return response(prefix + '\n\n' + slotChoices(slots) + '\n\nPuedes responder "el primero", "el de las 11" o con 1, 2, 3 o 4.');
}

if (session.step === 'awaiting_slot') {
  const idx = selectionIndex(text, session.offeredSlots || []);
  const looksLikeSelection = idx !== null && idx >= 0 && idx < (session.offeredSlots || []).length;

  if (!looksLikeSelection) {
    const pref = parsePreference(text);
    if (pref.recognized && !/^\s*[1-4]\s*$/.test(text)) {
      session.preference = pref;
      const revised = availableSlots(pref, 4);
      if (revised.length) {
        session.offeredSlots = revised;
        save();
        return response('Claro, te ajusté la búsqueda. Tengo:\n\n' + slotChoices(revised) + '\n\n¿Cuál te acomoda mejor?');
      }
    }
  }

  if (!looksLikeSelection) {
    return response('No alcancé a identificar cuál horario escogiste. Dime "el segundo", "el de las 11" o marca 1, 2, 3 o 4:\n\n' + slotChoices(session.offeredSlots || []));
  }

  const chosen = session.offeredSlots[idx];
  const alreadyTaken = Object.values(store.appointments).some((a) =>
    a && a.tenantId === tenantId && a.status === 'booked' && a.startsAt === chosen
  );
  if (alreadyTaken) {
    const refreshed = availableSlots(session.preference || {}, 4);
    session.offeredSlots = refreshed;
    save();
    return response('Ese horario acaba de ocuparse. Te actualizo las opciones:\n\n' + slotChoices(refreshed) + '\n\n¿Cuál prefieres?');
  }

  session.proposedSlot = chosen;
  save('awaiting_confirmation');
  const plateText = session.plate ? ' Placa: ' + session.plate + '.' : '';
  return response('Antes de reservar, te resumo todo:\n\n• Motivo: ' + session.serviceSummary + '\n• Horario: ' + slotLabel(chosen) + '.' + plateText + '\n\n¿Te lo confirmo así? Puedes decirme "sí" o "otra hora".');
}

if (session.step === 'awaiting_confirmation') {
  const correctedPlate = extractPlate(text);
  if (correctedPlate && correctedPlate !== session.plate) {
    session.plate = correctedPlate;
    save();
    return response('Listo, actualicé la placa a ' + correctedPlate + '. La propuesta sigue siendo ' + slotLabel(session.proposedSlot) + '. ¿Confirmo la reserva?');
  }

  if (isNoOrChange(text)) {
    return askPreference();
  }
  if (!isYes(text)) {
    const pref = parsePreference(text);
    if (pref.recognized) {
      session.preference = pref;
      const revised = availableSlots(pref, 4);
      if (revised.length) {
        session.offeredSlots = revised;
        save('awaiting_slot');
        return response('Entendido. Busqué ese nuevo horario y tengo:\n\n' + slotChoices(revised) + '\n\n¿Cuál prefieres?');
      }
    }
    return response('¿Confirmo la cita propuesta para ' + slotLabel(session.proposedSlot) + '? Puedes decir "sí" o "otra hora".');
  }

  const chosen = session.proposedSlot;
  if (!chosen) throw new Error('CASE002_APPOINTMENT_PROPOSED_SLOT_MISSING');

  const alreadyTaken = Object.values(store.appointments).some((a) =>
    a && a.tenantId === tenantId && a.status === 'booked' && a.startsAt === chosen
  );
  if (alreadyTaken) {
    const refreshed = availableSlots(session.preference || {}, 4);
    session.offeredSlots = refreshed;
    save('awaiting_slot');
    return response('Justo antes de confirmar, ese horario se ocupó. Estas son las opciones actualizadas:\n\n' + slotChoices(refreshed) + '\n\n¿Cuál te conviene?');
  }

  const appointmentId = 'case002_apt_' + Date.now() + '_' + senderId.slice(-4);
  const appointment = {
    id: appointmentId,
    tenantId,
    senderId,
    requestType: session.requestType || 'other',
    serviceSummary: String(session.serviceSummary || 'revisión de taller'),
    vehicleOperationalState: session.vehicleOperationalState || 'unknown',
    plate: session.plate || null,
    provider: 'case002-level2-internal',
    providerEventId: 'sandbox:' + appointmentId,
    startsAt: chosen,
    endsAt: new Date(new Date(chosen).getTime() + 60 * 60 * 1000).toISOString(),
    timezone,
    status: 'booked',
    sourceMessageId: providerMessageId,
    createdAt: now.toISOString()
  };
  store.appointments[appointmentId] = appointment;
  session.step = 'booked';
  session.lastAppointmentId = appointmentId;
  session.updatedAt = now.toISOString();
  store.sessions[sessionKey] = session;

  return response('Listo, registré tu cita para ' + slotLabel(chosen) + '. Motivo: ' + appointment.serviceSummary + (appointment.plate ? '. Placa: ' + appointment.plate : '') + '.\n\nSi luego necesitas revisar la hora o cancelarla, me avisas.');
}

if (session.step === 'booked') {
  const appointment = session.lastAppointmentId ? store.appointments[session.lastAppointmentId] : null;
  if (appointment && appointment.status === 'booked') {
    if (/\b(otra cita|nueva cita|otro vehiculo)\b/.test(lower)) {
      session = { step: 'idle', startedAt: now.toISOString() };
      store.sessions[sessionKey] = session;
      return response('Claro. Cuéntame qué necesitas hacerle al otro vehículo o qué estás notando.');
    }
    return response('Tu cita está registrada para ' + slotLabel(appointment.startsAt) + '. Si quieres, puedo recordarte el motivo, cancelar la cita o empezar otra reserva.');
  }
  session = { step: 'idle', updatedAt: now.toISOString() };
  store.sessions[sessionKey] = session;
  return response('No encuentro una cita activa. Cuéntame qué necesitas y empezamos.');
}

throw new Error('CASE002_APPOINTMENT_AGENT_UNKNOWN_STATE ' + session.step);

const input = $input.first().json || {};
const fallback = String(input.fallbackText || input.text || '').trim();
if (!fallback) throw new Error('CASE002_RENDER_FALLBACK_MISSING');

const plan = input.responsePlan || {};
const protectedFacts = Array.isArray(plan.protectedFacts) ? plan.protectedFacts.map(String) : [];
const forbiddenTerms = Array.isArray(plan.forbiddenTerms) ? plan.forbiddenTerms.map(String) : [];
const candidate = input.rendererMeta?.ok === true ? String(input.renderedReply || '').trim() : '';

function fold(value) {
  return String(value || '').toLocaleLowerCase('es-PE').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

let accepted = !!candidate && candidate.length <= 1200;
if (accepted) {
  for (const fact of protectedFacts) {
    if (fact && !candidate.includes(fact)) {
      accepted = false;
      break;
    }
  }
}

if (accepted) {
  const foldedCandidate = fold(candidate);
  for (const term of forbiddenTerms) {
    const foldedTerm = fold(term).trim();
    if (!foldedTerm) continue;
    const special = '\\^$.*+?()[]{}|';
    const escaped = Array.from(foldedTerm).map((ch) => special.includes(ch) ? '\\' + ch : ch).join('');
    const pattern = new RegExp('(^|[^a-z0-9])' + escaped + '([^a-z0-9]|$)', 'i');
    if (pattern.test(foldedCandidate)) {
      accepted = false;
      break;
    }
  }
}

const allowedCorpus = [fallback, ...protectedFacts].join(' ');
function hasUnknown(pattern) {
  const tokens = candidate.match(pattern) || [];
  return tokens.some((token) => !allowedCorpus.includes(token));
}

if (accepted && hasUnknown(/\b[0-3]?\d\/[01]?\d\b/g)) accepted = false;
if (accepted && hasUnknown(/\b(?:[01]?\d|2[0-3]):[0-5]\d\b/g)) accepted = false;
if (accepted && hasUnknown(/\b[A-Z0-9]{3}-[A-Z0-9]{3}\b/g)) accepted = false;
if (accepted && hasUnknown(/(?:S\/|\$)\s?\d+(?:[.,]\d+)?/g)) accepted = false;

const finalText = accepted ? candidate : fallback;

const tenantId = String(input.tenantId || '');
const senderId = String(input.senderId || input.to || '').replace(/[^0-9]/g, '');
const recipient = String(input.to || input.senderId || '').replace(/[^0-9]/g, '');
if (!recipient) throw new Error('CASE002_RENDER_RECIPIENT_MISSING');
if (tenantId && senderId) {
  const store = $getWorkflowStaticData('global');
  store.sessions = store.sessions || {};
  const session = store.sessions[tenantId + ':' + senderId];
  if (session && Array.isArray(session.history)) {
    for (let i = session.history.length - 1; i >= 0; i--) {
      if (session.history[i]?.role === 'assistant') {
        session.history[i].content = finalText.slice(0, 1200);
        break;
      }
    }
    session.updatedAt = new Date().toISOString();
  }
}

return [{
  json: {
    ...input,
    senderId: senderId || recipient,
    to: recipient,
    text: finalText,
    renderValidation: {
      accepted,
      fallbackUsed: !accepted,
      provider: input.rendererMeta?.provider || 'none'
    }
  }
}];

const result = $input.first().json || {};
if (result.status !== 'accepted_by_provider') throw new Error('CASE002_APPOINTMENT_REPLY_NOT_ACCEPTED');
if (!result.providerMessageId) throw new Error('CASE002_APPOINTMENT_REPLY_PROVIDER_MESSAGE_ID_MISSING');
return [{ json: {
  ok: true,
  status: result.status,
  providerMessageId: String(result.providerMessageId),
  businessActionId: String(result.businessActionId || '')
} }];
